  "steps.m.crossBeams.oneSimple": "uiteinde {n} vrij opgelegd (3EI/L)",
  "steps.m.crossBeams.bothHeld": "beide vastgehouden (4EI/L)",
  "steps.m.crossBeams.stiffnessCaption": "Stijfheid van elk veld aan de uiteinden die in evenwicht worden gebracht.",
